// unavailable is the error for a call into a module that is not loaded.
func (m *WasmModule) unavailable() error {
	if m.initErr != nil {
		return m.initErr
	}
	return errors.New("the Graphviz WebAssembly module is not loaded")
}

// registerCallback runs a write to the callback maps under the module's
// lock, since host functions read them under it.
func (m *WasmModule) registerCallback(write func()) {
	_, leave, _ := m.lock.enter(context.Background())
	defer leave()
	write()
}

// invoke runs one exported function under the module's lock: one call at a
// time, process-wide, since Graphviz is single-threaded and wazero's Call
// is not goroutine-safe. The lock is re-entrant on the goroutine holding
// it, which is how a host function (Go code Graphviz called) reaches back
// into the module.
func (m *WasmModule) invoke(ctx context.Context, name string, args ...uint64) ([]uint64, error) {
	if m.mod == nil {
		return nil, m.unavailable()
	}
	ctx, leave, outermost := m.lock.enter(ctx)
	defer leave()
	fn, done := m.function(name)
	ret, err := fn.Call(ctx, args...)
	done()
	if !outermost {
		// A nested call (a host function reaching back in, a free after a
		// callback failed) leaves the parked error to the call that owns it.
		return ret, err
	}
	if err != nil {
		// A trap can follow from a callback's failure (its out-parameters
		// were never written), so a parked error is returned with it.
		return nil, errors.Join(err, m.takeCallbackError())
	}
	if err := m.takeCallbackError(); err != nil {
		return nil, err
	}
	return ret, nil
}

// malloc allocates size bytes in the module. A size past the 32-bit address
// space, or one the module cannot grow to hold, is ErrOutOfMemory: writing
// to the null pointer malloc returns then would overwrite low memory.
func (m *WasmModule) malloc(ctx context.Context, size uint64) (uint64, error) {
	if size > maxAllocation {
		return 0, fmt.Errorf("%w: %d bytes", ErrOutOfMemory, size)
	}
	ret, err := m.invoke(ctx, "malloc", size)
	if err != nil {
		return 0, err
	}
	if ret[0] == 0 && size > 0 {
		return 0, fmt.Errorf("%w: %d bytes", ErrOutOfMemory, size)
	}
	return ret[0], nil
}

func (m *WasmModule) free(ctx context.Context, p uint64) error {
	if _, err := m.invoke(ctx, "free", p); err != nil {
		return err
	}
	return nil
}

func (m *WasmModule) newObject(ctx context.Context, name string) (uint64, error) {
	ret, err := m.invoke(ctx, "wasm_bridge_new_"+name)
	if err != nil {
		return 0, err
	}
	return ret[0], nil
}

func (m *WasmModule) setField(ctx context.Context, name string, recv, arg uint64) error {
	if _, err := m.invoke(ctx, "wasm_bridge_set_"+name, recv, arg); err != nil {
		return err
	}
	return nil
}

func (m *WasmModule) setFieldFunction(ctx context.Context, name string, recv uint64) error {
	if _, err := m.invoke(ctx, "wasm_bridge_set_"+name, recv); err != nil {
		return err
	}
	return nil
}

func (m *WasmModule) getField(ctx context.Context, name string, recv uint64) (ret uint64, e error) {
	retPtr, err := m.NewPtr(ctx)
	if err != nil {
		return 0, err
	}
	defer func() {
		if ferr := m.free(ctx, retPtr); ferr != nil && e == nil {
			e = ferr
		}
	}()

	if _, err := m.invoke(ctx, "wasm_bridge_get_"+name, recv, retPtr); err != nil {
		return 0, err
	}
	p, err := m.readU64(ctx, retPtr)
	if err != nil {
		return 0, err
	}
	return p, nil
}

// call runs a bridge function. An error a Go callback returned while the
// function ran comes back from here, after Graphviz has unwound normally;
// a wazero error (a trap, a panic in a callback) comes back as is.
func (m *WasmModule) call(ctx context.Context, name string, args ...uint64) error {
	_, err := m.invoke(ctx, "wasm_bridge_"+name, args...)
	return err
}

func (m *WasmModule) callWithRet(ctx context.Context, name string, args ...uint64) (r uint64, e error) {
	retPtr, err := m.NewPtr(ctx)
	if err != nil {
		return 0, err
	}
	defer func() {
		if ferr := m.free(ctx, retPtr); ferr != nil && e == nil {
			e = ferr
		}
	}()

	if err := m.call(ctx, name, append(append([]uint64{}, args...), retPtr)...); err != nil {
		return 0, err
	}
	p, err := m.readU64(ctx, retPtr)
	if err != nil {
		return 0, err
	}
	return p, nil
}

// The memory helpers hold the lock too: another goroutine's call can grow
// the memory, which moves it.
func (m *WasmModule) read(ctx context.Context, addr, length uint64) ([]byte, error) {
	if m.mod == nil {
		return nil, m.unavailable()
	}
	_, leave, _ := m.lock.enter(ctx)
	defer leave()
	view, ok := m.mod.Memory().Read(uint32(addr), uint32(length))
	if !ok {
		return nil, fmt.Errorf(
			`failed to read wasm memory: (ptr, size) = (%d, %d) and memory size is %d`,
			addr, length, m.mod.Memory().Size(),
		)
	}
	// Read returns a view of the module's memory, which another call may
	// move or overwrite once the lock is released; the caller gets a copy.
	return bytes.Clone(view), nil
}

func (m *WasmModule) readU32(ctx context.Context, addr uint64) (uint64, error) {
	if m.mod == nil {
		return 0, m.unavailable()
	}
	_, leave, _ := m.lock.enter(ctx)
	defer leave()
	p, ok := m.mod.Memory().ReadUint32Le(uint32(addr))
	if !ok {
		return 0, fmt.Errorf(
			`failed to read wasm memory: (ptr, size) = (%d, 4) and memory size is %d`,
			addr, m.mod.Memory().Size(),
		)
	}
	return uint64(p), nil
}

// readU64 reads a slot NewPtr allocated: the eight bytes the bridge wrote,
// or a 32-bit value with the zeroed upper half.
func (m *WasmModule) readU64(ctx context.Context, addr uint64) (uint64, error) {
	if m.mod == nil {
		return 0, m.unavailable()
	}
	_, leave, _ := m.lock.enter(ctx)
	defer leave()
	p, ok := m.mod.Memory().ReadUint64Le(uint32(addr))
	if !ok {
		return 0, fmt.Errorf(
			`failed to read wasm memory: (ptr, size) = (%d, 8) and memory size is %d`,
			addr, m.mod.Memory().Size(),
		)
	}
	return p, nil
}

func (m *WasmModule) write(ctx context.Context, p uint64, b []byte) error {
	if m.mod == nil {
		return m.unavailable()
	}
	_, leave, _ := m.lock.enter(ctx)
	defer leave()
	if !m.mod.Memory().Write(uint32(p), b) {
		return fmt.Errorf(
			`failed to write wasm memory: (ptr, size) = (%d, %d) and memory size is %d`,
			p, len(b), m.mod.Memory().Size(),
		)
	}
	return nil
}

func (m *WasmModule) writeU32(ctx context.Context, p uint64, v uint32) error {
	if m.mod == nil {
		return m.unavailable()
	}
	_, leave, _ := m.lock.enter(ctx)
	defer leave()
	if !m.mod.Memory().WriteUint32Le(uint32(p), v) {
		return fmt.Errorf(
			`failed to write wasm memory: ptr = %d and memory size is %d`,
			p, m.mod.Memory().Size(),
		)
	}
	return nil
}

func (m *WasmModule) writeU64(ctx context.Context, p uint64, v uint64) error {
	if m.mod == nil {
		return m.unavailable()
	}
	_, leave, _ := m.lock.enter(ctx)
	defer leave()
	if !m.mod.Memory().WriteUint64Le(uint32(p), v) {
		return fmt.Errorf(
			`failed to write wasm memory: ptr = %d and memory size is %d`,
			p, m.mod.Memory().Size(),
		)
	}
	return nil
}

func (m *WasmModule) writeF64(ctx context.Context, p uint64, v float64) error {
	if m.mod == nil {
		return m.unavailable()
	}
	_, leave, _ := m.lock.enter(ctx)
	defer leave()
	if !m.mod.Memory().WriteFloat64Le(uint32(p), v) {
		return fmt.Errorf(
			`failed to write wasm memory: ptr = %d and memory size is %d`,
			p, m.mod.Memory().Size(),
		)
	}
	return nil
}

// NewPtr allocates a one-word slot for a value a bridge function hands back.
// It starts zeroed: a function that fails never writes its out-parameters,
// and a null there reads back as a nil object or an empty string instead of
// whatever the allocator left.
func (m *WasmModule) NewPtr(ctx context.Context) (uint64, error) {
	// Eight bytes: the bridge writes a 64-bit field's value whole into the
	// slot, and a pointer or a 32-bit value into its low half.
	p, err := m.malloc(ctx, 8)
	if err != nil {
		return 0, err
	}
	if err := m.writeU64(ctx, p, 0); err != nil {
		return 0, err
	}
	return p, nil
}

// toSlice reads the GoSlice at p, a header and a data array the C bridge
// allocates for every slice it hands out, and frees both; the elements are
// the caller's to read and, where they are copies, to free.
func (m *WasmModule) toSlice(ctx context.Context, p uint64) ([]uint64, error) {
	defer m.free(ctx, p)
	length, err := m.readU32(ctx, p)
	if err != nil {
		return nil, err
	}
	data, err := m.readU32(ctx, p+4)
	if err != nil {
		return nil, err
	}
	if data != 0 {
		defer m.free(ctx, data)
	}
	var ret []uint64
	for i := uint64(0); i < length; i++ {
		p, err := m.readU32(ctx, data+8*i)
		if err != nil {
			return nil, err
		}
		ret = append(ret, p)
	}
	return ret, nil
}

